from typing import List, Dict, Any, Callable

def group_by_key(items: List[Dict[str, Any]], key: str, group_func: Callable[[Any], Any]) -> Dict[Any, List[Dict[str, Any]]]:
    grouped = {}
    for item in items:
        group_key = group_func(item.get(key))
        if group_key not in grouped:
            grouped[group_key] = []
        grouped[group_key].append(item)
    return grouped
